def _serialize_tensor_value(value):
    """Convert a value stored in a :class:`TensorData` to a JSON-serializable structure."""
    if isinstance(value, np.ndarray):
        return {
            "__ndarray__": True,
            "dtype": str(value.dtype),
            "shape": list(value.shape),
            "data": value.ravel().tolist(),
        }
    if isinstance(value, np.generic):
        # Scalar numpy values (e.g. np.int64 bins) are stored as plain python scalars.
        return value.item()
    return value


def _deserialize_tensor_value(value):
    """Reconstruct a value produced by :func:`_serialize_tensor_value`."""
    if isinstance(value, dict) and value.get("__ndarray__"):
        arr = np.array(value["data"], dtype=np.dtype(value["dtype"]))
        return arr.reshape(tuple(value["shape"]))
    return value


